# rebuild old-style f
import scipy.ndimage
def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[row[:] for row in g]
    # find connected components (4-conn) of non-bg
    lab,n=scipy.ndimage.label((g!=bg).astype(bool))
    objs=[]
    for i in range(1,n+1):
        pts=[(r,c) for r in range(H) for c in range(W) if lab[r][c]==i]
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        col=g[pts[0][0]][pts[0][1]]
        objs.append((pts,r0,r1,c0,c1,col))
    # seeds: touch border
    def touches(p,bbox):
        r,c=p
        return r==bbox[0] or r==bbox[1] or c==bbox[2] or c==bbox[3]
    for pts,r0,r1,c0,c1,col in objs:
        if touches(pts,(r0,r1,c0,c1)):
            for (r,c) in pts:
                if c==c0: continue  # will handle
            # band rows r0-1..r0+1 full width, parity mask
            rr=list(range(r0-1,r1+2))
            for r in rr:
                for cc in range(W):
                    if (r+cc)%2==0:
                        out[r][cc]=col
            break
    return out
